import{z as o,x as A,o as s,c,q as B,j as n,D as i,d as e,s as t,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"公平性度量","description":"","frontmatter":{"title":"公平性度量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fairness-metrics.md","filePath":"cs/fairness-metrics.md","lastUpdated":1791413859000}'),p={name:"cs/fairness-metrics.md"};function d(m,a,C,u,D,f){const r=A("Mermaid");return s(),c("div",null,[a[2]||(a[2]=B('<h1 id="公平性度量" tabindex="-1">公平性度量 <a class="header-anchor" href="#公平性度量" aria-label="Permalink to &quot;公平性度量&quot;">​</a></h1><div class="epigraph"><p>公平不是口号：Jain 指数、滞后、每任务实际份额对权重的偏差，才能比较 CFS、EEVDF 与组调度。</p><footer>—— 据 Jain, Chiu, Hawe 对公平指数的定义；Silberschatz 对调度指标的整理；[调度指标](/cs/scheduling-metrics) 为先修</footer></div><p><a href="/cs/cooperative-scheduling">协作</a> 会饿死。<a href="/cs/eevdf">EEVDF</a>/<a href="/cs/cgroup-cpu-sched">cgroup</a> 声称公平。缺口是 <strong>量公平</strong>：与 <a href="/cs/latency-measurement">cyclictest</a> 的延迟维正交。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>吞吐高可以很不公平。滞后（lag）：应得虚拟时间与实际之差。Jain：\\((\\sum x_i)^2 / (n \\sum x_i^2)\\) 近 1 则均。缺口：加权公平要把 \\(x_i\\) 除以权重；短任务样本会噪；与尾延迟同时报才完整。本课不把排队论证明写完。</p><p><span class="marginnote">max-min 公平是另一目标。网络 qdisc 的 fq 也在用类似语言，对象不同。</span><span class="marginnote">数字实例：Jain 指数 \\((\\sum x_i)^2/(n\\sum x_i^2)\\)，4 个任务平分（各 1）得 \\(16/(4\\times4)=1\\)；一个任务独占（4,0,0,0）得 \\(16/(4\\times16)=0.25=1/n\\)。它只衡量「摊得匀不匀」，不管蛋糕总共多大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跑混合负载 → 记每任务 CPU 时间 → 算加权份额误差与 Jain。对照 blk BFQ 的带宽公平。对照 <a href="/cs/memcg">memcg</a>：内存没有 Jain 默认，但可同样定义。对照 RT：公平让位于截止。<span class="marginnote">术语翻译：滞后（lag）就是「按权重它此刻应得的运行时间」减去「实际拿到的运行时间」——长期大于 0 是被亏待，长期小于 0 是占了便宜，理想状态是贴着 0 上下抖动。</span></p>',8)),(s(),n(l,null,{default:i(()=>[t(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E6%AF%8F%E4%BB%BB%E5%8A%A1%20CPU%20%E6%97%B6%E9%97%B4%22%5D%20--%3E%20W%5B%22%E6%8C%89%E6%9D%83%E9%87%8D%E5%BD%92%E4%B8%80%22%5D%0A%20%20W%20--%3E%20J%5B%22Jain%20%E6%88%96%E6%BB%9E%E5%90%8E%22%5D%0A%20%20LAT%5B%22%E5%B0%BE%E5%BB%B6%E8%BF%9F%22%5D%20--%3E%20REP%5B%22%E4%B8%8E%E5%85%AC%E5%B9%B3%E4%B8%80%E8%B5%B7%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("度量让调度课从故事变成可证伪。没有它，EAS 省电也可能被说成「更公平」。不要写成论文造数。与 "),E("a",{href:"/cs/perf-sampling"},"perf"),e(" 后课：采样是工具，指标是定义。")],-1)),a[5]||(a[5]=E("p",null,"实验必须固定拓扑与频率，否则公平被 DVFS 搅浑——下一课 governor。",-1)),(s(),n(l,null,{default:i(()=>[t(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B5%8B%E5%BE%97%E5%90%84%E4%BB%BB%E5%8A%A1%E4%BB%BD%E9%A2%9D%20x_i%22%5D%20--%3E%20J%5B%22%E7%AE%97%20Jain%20%E6%8C%87%E6%95%B0%22%5D%0A%20%20J%20--%3E%20R%7B%22%E6%8C%87%E6%95%B0%E6%9C%89%E5%A4%9A%E6%8E%A5%E8%BF%91%201%EF%BC%9F%22%7D%0A%20%20R%20--%3E%7C%22%E7%BA%A6%E7%AD%89%E4%BA%8E%201%22%7C%20EQ%5B%22%E4%BB%BD%E9%A2%9D%E5%9D%87%E8%A1%A1%EF%BC%8C%E5%85%AC%E5%B9%B3%E6%80%A7%E5%A5%BD%22%5D%0A%20%20R%20--%3E%7C%22%E6%98%8E%E6%98%BE%E5%B0%8F%E4%BA%8E%201%22%7C%20UN%5B%22%E6%9C%89%E4%BA%BA%E6%8B%BF%E5%BE%97%E8%BF%87%E5%A4%9A%EF%BC%8C%E6%9F%A5%E6%9D%83%E9%87%8D%E5%BD%92%E4%B8%80%22%5D%0A%20%20UN%20--%3E%20C%7B%22%E6%9C%89%E6%B2%A1%E6%9C%89%E4%BB%BB%E5%8A%A1%E4%BB%BD%E9%A2%9D%E6%8E%A5%E8%BF%91%200%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E6%9C%89%22%7C%20ST%5B%22%E5%85%88%E4%BF%AE%E9%A5%BF%E6%AD%BB%EF%BC%9A%E5%85%AC%E5%B9%B3%E5%B7%B2%E7%BB%8F%E7%A0%B4%E4%BA%A7%22%5D%0A%20%20C%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20WN%5B%22%E6%8A%8A%20x_i%20%E9%99%A4%E4%BB%A5%E6%9D%83%E9%87%8D%E5%86%8D%E7%AE%97%E4%B8%80%E6%AC%A1%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">常见误区：初学者容易把「公平」当成「延迟低」；这是两个正交指标——调度器可以把 CPU 份额切得极其公平，同时让每个任务的完成时间（尾延迟）变长。所以实验报告必须把公平与尾延迟分开列出。</span></p><p>实现上：短任务样本会让 Jain 指数噪声很大，要按加权 CPU 时间而非完成个数。DVFS 让「时间份额」和「指令份额」分家，实验要锁频。滞后可正可负，长期应在零附近。 读法上只引用<a href="/cs/cooperative-scheduling">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>公平性度量</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有学术公平定义。不保证云「可抢占 VM」的商业公平。下一课频率：cpufreq governor。</p><p>版本字段会变，课序钉的是机制对象「公平性度量」，不是某一主线内核的结构体名。 后课默认：公平用份额偏差/Jain 等可计算。CPU 频率策略，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公平用滞后、加权份额、Jain 等度量。</li><li>必须与延迟分开报告。</li><li>cpufreq governor 是下一课。</li><li>出处：Jain et al.；Silberschatz <em>OSC</em>；Linux 调度文档。</li></ul>',9))])}const g=o(p,[["render",d]]);export{_ as __pageData,g as default};
